contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint countBefore = c.depositsCount();
        uint balBefore = address(c).balance;
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);
        assert(c.depositsCount() == countBefore + 1 && address(c).balance == balBefore + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint amount) public {
        require(amount > address(c).balance);
        uint countBefore = c.depositsCount();
        bool reverted;
        try c.sendMoney(target, amount) { reverted = false; } catch { reverted = true; }
        assert(reverted && c.depositsCount() == countBefore);
    }
    receive() external payable {}
}
